function renderVirtualList(container, rows, rowHeight) {
  const start = Math.floor(container.scrollTop / rowHeight);
  const visibleCount = Math.ceil(container.clientHeight / rowHeight) + 4;
  const slice = rows.slice(start, start + visibleCount);
  const inner = document.createElement("div");
  inner.style.position = "relative";
  inner.style.height = `${rows.length * rowHeight}px`;

  for (let index = 0; index < slice.length; index += 1) {
    const row = document.createElement("div");
    row.textContent = slice[index].label;
    row.style.position = "absolute";
    row.style.top = `${(start + index) * rowHeight}px`;
    inner.append(row);
  }

  container.replaceChildren(inner);
}

function renderTabs(root, tabs) {
  const header = document.createElement("div");
  const body = document.createElement("div");
  let activeId = tabs[0]?.id;

  function refresh() {
    header.replaceChildren();
    body.replaceChildren();
    for (const tab of tabs) {
      const button = document.createElement("button");
      button.textContent = tab.label;
      button.className = tab.id === activeId ? "active" : "";
      button.onclick = () => { activeId = tab.id; refresh(); };
      header.append(button);
      if (tab.id === activeId) body.append(tab.render());
    }
  }

  refresh();
  root.replaceChildren(header, body);
}

function renderTable(root, columns, rows) {
  let currentRows = [...rows];
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const tbody = document.createElement("tbody");

  const headerRow = document.createElement("tr");
  for (const column of columns) {
    const cell = document.createElement("th");
    cell.textContent = column.label;
    cell.onclick = () => {
      currentRows.sort((a, b) => String(a[column.key]).localeCompare(String(b[column.key])));
      drawBody();
    };
    headerRow.append(cell);
  }
  thead.append(headerRow);

  function drawBody() {
    tbody.replaceChildren();
    for (const row of currentRows) {
      const tr = document.createElement("tr");
      for (const column of columns) {
        const td = document.createElement("td");
        td.textContent = row[column.key];
        tr.append(td);
      }
      tbody.append(tr);
    }
  }

  drawBody();
  table.append(thead, tbody);
  root.replaceChildren(table);
}

