const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
const { data } = imageData;

for (let i = 0; i < data.length; i += 4) {
  const r = data[i + 0];
  const g = data[i + 1];
  const b = data[i + 2];
  const gray = Math.round(0.299 * r + 0.587 * g + 0.114 * b);
  data[i + 0] = gray;
  data[i + 1] = gray;
  data[i + 2] = gray;
}

ctx.putImageData(imageData, 0, 0);

