const view = { x: 0, y: 0, zoom: 1 };

function render(ctx) {
  ctx.save();
  ctx.setTransform(view.zoom, 0, 0, view.zoom, view.x, view.y);
  ctx.clearRect(-view.x / view.zoom, -view.y / view.zoom, ctx.canvas.width / view.zoom, ctx.canvas.height / view.zoom);
  ctx.fillRect(50, 50, 120, 80);
  ctx.restore();
}

const selection = { x: 60, y: 40, width: 140, height: 90 };

function drawSelection(ctx) {
  ctx.save();
  ctx.strokeStyle = "#00aaff";
  ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
  [[selection.x, selection.y], [selection.x + selection.width, selection.y + selection.height]].forEach(([x, y]) => {
    ctx.fillRect(x - 4, y - 4, 8, 8);
  });
  ctx.restore();
}

const sprite = new Image();
sprite.src = "spritesheet.png";
let frameIndex = 0;

function drawFrame(ctx) {
  const frameWidth = 64;
  const frameHeight = 64;
  const sx = frameIndex * frameWidth;
  ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  ctx.drawImage(sprite, sx, 0, frameWidth, frameHeight, 20, 20, frameWidth, frameHeight);
  frameIndex = (frameIndex + 1) % 8;
  requestAnimationFrame(() => drawFrame(ctx));
}

const tileSize = 32;
const map = [
  [1, 1, 1, 1],
  [1, 0, 0, 1],
  [1, 0, 2, 1],
  [1, 1, 1, 1]
];

function drawMap(ctx) {
  map.forEach((row, y) => row.forEach((tile, x) => {
    if (tile === 0) return;
    ctx.fillStyle = tile === 1 ? "#666" : "#ffcc00";
    ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
  }));
}

function drawNeedle(ctx, angle) {
