const points = [12, 30, 18, 42, 26, 55, 38];
const width = 500;
const height = 180;
const stepX = width / (points.length - 1);
const maxY = Math.max(...points);

const polylinePoints = points
  .map((value, index) => {
    const x = index * stepX;
    const y = height - (value / maxY) * (height - 20) - 10;
    return `${x},${y}`;
  })
  .join(" ");

document.querySelector("svg").innerHTML = `
  <polyline
    fill="none"
    stroke="#2563eb"
    stroke-width="3"
    points="${polylinePoints}"
