    setError("");
    const previous = items;
    const optimistic = items.map(item => item.id === id ? { ...item, done: !item.done } : item);
    setItems(optimistic);
    try {
      const changed = optimistic.find(item => item.id === id);
      const response = await fetch(`/api/todos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ done: changed.done })
