export function StreamReader() {
  const [rows, setRows] = useState([]);

  async function start() {
    const response = await fetch("/api/stream");
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const parts = buffer.split("
");
      buffer = parts.pop() ?? "";
      for (const line of parts) {
        if (line.trim()) setRows(current => [...current, JSON.parse(line)]);
      }
    }
  }

  return <button onClick={start}>Start stream</button>;
}

import React, { useEffect, useRef, useState } from "react";

export function InfiniteList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const markerRef = useRef(null);

  useEffect(() => {
    fetch(`/api/items?page=${page}`)
      .then(response => response.json())
      .then(data => setItems(current => [...current, ...data.items]));
  }, [page]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0]?.isIntersecting) setPage(current => current + 1);
    });
    if (markerRef.current) observer.observe(markerRef.current);
    return () => observer.disconnect();
  }, []);

  return <div><div ref={markerRef} /></div>;
}

