export function useOptimisticList(initialRows) {
  const rows = ref(initialRows);

  async function mutate(id, patch) {
    const previous = structuredClone(rows.value);
    rows.value = rows.value.map(row => row.id === id ? { ...row, ...patch } : row);
    try {
      const response = await fetch(`/api/rows/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(patch)
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
    } catch (error) {
      rows.value = previous;
      throw error;
    }
  }

  return { rows, mutate };
}

function createStore(initialState) {
  let state = initialState;
  const listeners = new Set();
  return {
    getState: () => state,
    setState: (patch) => {
      state = { ...state, ...patch };
      listeners.forEach((listener) => listener(state));
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

