import { createHmac, timingSafeEqual } from 'node:crypto';

function verifyWebhookSignature(secret, rawBody, receivedSignature) {
  const expected = createHmac('sha256', secret).update(rawBody).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(receivedSignature || '');
  return a.length === b.length && timingSafeEqual(a, b);
}

const idempotencyStore = new Map();

function idempotencyMiddleware(req, res, next) {
  const key = req.get('idempotency-key');
  if (!key) return next();

  const cached = idempotencyStore.get(key);
  if (cached) {
    return res.status(cached.status).json(cached.body);
  }

  const originalJson = res.json.bind(res);
  res.json = (body) => {
    idempotencyStore.set(key, { status: res.statusCode, body });
    return originalJson(body);
  };
  next();
}

router.put('/:id', async (req, res) => {
  const current = await repo.getById(req.params.id);
  const expected = `W/"${current.version}"`;

  if (req.get('if-match') !== expected) {
    return res.status(412).json({ error: 'precondition_failed', expected });
  }

  const updated = await repo.update(req.params.id, req.body, current.version);
  res.set('etag', `W/"${updated.version}"`).json(updated);
});

