async function withDeadlockRetry(work, attempts = 3) {
  for (let i = 0; i < attempts; i += 1) {
    try {
      return await work();
    } catch (error) {
      if (error?.code !== 'ER_LOCK_DEADLOCK' || i === attempts - 1) {
        throw error;
      }
    }
  }
}

