let cursor = 0;
const batchSize = 500;

while (true) {
  const rows = await db.query(
    'SELECT id, legacy_value FROM items WHERE id > $1 ORDER BY id ASC LIMIT $2',
    [cursor, batchSize]
  );
  if (rows.rowCount === 0) break;

  for (const row of rows.rows) {
    await db.query('UPDATE items SET normalized_value = $1 WHERE id = $2', [normalize(row.legacy_value), row.id]);
    cursor = row.id;
  }
}

