async function timedQuery(db, sql, params) {
  const startedAt = performance.now();
  try {
    return await db.query(sql, params);
  } finally {
    const durationMs = performance.now() - startedAt;
    if (durationMs > 200) {
      console.warn('slow query', { durationMs, sql });
    }
  }
}

