async function retryTransient(work, attempts = 4) {
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await work();
    } catch (error) {
      const code = error?.code;
      const transient = code === '40001' || code === '40P01' || code === 'ER_LOCK_DEADLOCK';
      if (!transient || attempt === attempts) throw error;
      await new Promise((r) => setTimeout(r, attempt * 100));
    }
  }
}

async function queryWithContext(db, ctx, sql, params) {
  const startedAt = Date.now();
  try {
    return await db.query(sql, params);
  } finally {
    console.info({ requestId: ctx.requestId, sql, durationMs: Date.now() - startedAt });
  }
}

async function pollOutbox(db, publisher) {
  const rows = await db.query(
    `SELECT id, topic, payload
     FROM outbox_events
     WHERE published_at IS NULL
     ORDER BY id ASC
     LIMIT 100`
  );

  for (const row of rows.rows) {
    await publisher.publish(row.topic, row.payload);
    await db.query('UPDATE outbox_events SET published_at = NOW() WHERE id = $1', [row.id]);
  }
}

