const { spawn } = require("child_process");

function runTool(mainWindow, command, args) {
  const child = spawn(command, args, { shell: true });
  child.stdout.on("data", chunk => mainWindow.webContents.send("tool-output", chunk.toString()));
  child.stderr.on("data", chunk => mainWindow.webContents.send("tool-error", chunk.toString()));
  child.on("close", code => mainWindow.webContents.send("tool-exit", code));
}

const fs = require("fs");
const https = require("https");

function downloadFile(mainWindow, url, destination) {
  https.get(url, response => {
    const total = Number(response.headers["content-length"] || 0);
    let received = 0;
    const file = fs.createWriteStream(destination);
    response.on("data", chunk => {
      received += chunk.length;
      mainWindow.webContents.send("download-progress", { received, total });
    });
    response.pipe(file);
  });
}

