const pending = new Map();

window.chrome.webview.addEventListener("message", event => {
  const { id, result, error } = event.data;
  const handlers = pending.get(id);
  if (!handlers) return;
  pending.delete(id);
  if (error) handlers.reject(error); else handlers.resolve(result);
});

